import traceback

from pathlib import Path
from taf.config.testline import SerialOverHost, SerialOverTcp, LMI, CoreUnit, CommonUnit, RealEnb, ClassicalBts, RU
from taf.hw.rf_diagnostic_card import rf_diagnostic_card

from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, verify_function_x_times_with_ret, \
    wait_until_success
from taf.rfrl.utilities.robot.general import get_builtin_value


class Mumin:
    def __init__(self, nodes_details, lmi_logs_dir: str):
        self.nodes_details = nodes_details
        self.passed_rmods = []
        self.faulty_rmods = []
        self.failed_rmods = []
        self.lmi_rmods = set()
        self.rf_diagnostic_card = rf_diagnostic_card()
        self.connection_setup = self._get_rdc_config()
        self.lmi_logs_dir = lmi_logs_dir

    def setup_mumin(self):
        self.rf_diagnostic_card.prepare_log_directory_and_connection_setup(main_log_directory=self.lmi_logs_dir,
                                                                           connection_setup=self.connection_setup)
        self._set_lmi_rmods()
        self._setup_lmi_rmods()

    def disconnect_all_rmods(self):
        self.rf_diagnostic_card.disconnect_all_rmods()

    def teardown_mumin(self):
        test_logger(f"Tearing down MUMIN connections")
        try:
            if self.rf_diagnostic_card.rmod_connections:
                self.rf_diagnostic_card.disconnect_all_rmods()
        except Exception as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

    @staticmethod
    def _get_rdc_config():
        try:
            rdc_config = get_builtin_value("RDC_CONFIG")
            if rdc_config and Path(rdc_config).is_file():
                test_logger(f"Utilizing MUMIN configuration file: {rdc_config}")
                return rdc_config
            else:
                test_logger("No MUMIN configuration file provided - default will be used")
                return None
        except Exception as e:
            test_logger("No MUMIN configuration file provided - default will be used")
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug")
            return None

    def _set_lmi_rmods(self):
        try:
            for node in self.nodes_details:
                if 'mumin_config' in node:
                    self.add_ru_to_lmi_rmods(node)
                elif 'testline_object' in node:
                    testline_object = node['testline_object']
                    if isinstance(testline_object, RealEnb):
                        self.process_node(testline_object)
                    elif isinstance(testline_object, ClassicalBts):
                        self.process_classical_bts(testline_object)

        except Exception as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

    def _setup_lmi_rmods(self):
        for ru in self.lmi_rmods:
            self.setup_rmod(ru)

    def setup_rmod_from_serial(self, serial: str):
        for ru in self.lmi_rmods:
            if ru.serial_number == serial:
                self.setup_rmod(ru)
                break

    def setup_rmod(self, ru: RU):
        def log_setup_status():
            rmod_host = ""
            if isinstance(ru.lmi, SerialOverHost):
                rmod_host = ru.lmi.host.default_ssh_connection_details.addr
            elif isinstance(ru.lmi, SerialOverTcp):
                rmod_host = f"directly on {ru.lmi.uart_mapping[index].addr}:{ru.lmi.uart_mapping[index].port}"
            elif isinstance(ru.lmi, LMI):
                rmod_host = f"via host {ru.lmi.host.default_ssh_connection_details.addr}"
            if rmod_host:
                test_logger(f"Successfully set up {'LMI' if isinstance(ru.lmi, LMI) else 'MUMIN'} on "
                            f"{alias} {rmod_host}")

        test_logger(f"Trying to setup RU {ru.serial_number} with mumin/lmi")
        try:

            aliases, exceptions = self.setup_rmod_connections(ru)
            if exceptions:
                self.faulty_rmods.append({ru.serial_number: exceptions})
                test_logger(f"Minor issues during mumin setup {exceptions}", "warn")
            for index, alias in enumerate(aliases):
                self.passed_rmods.append(alias)
                log_setup_status()
        except Exception as e:
            self.failed_rmods.append([ru.serial_number, e])
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

    def process_units(self, units):
        for unit in units:
            if isinstance(unit, CoreUnit):
                self.add_rmods_from_unit(unit.rus)
            elif isinstance(unit, CommonUnit):
                self.add_rmods_from_common_unit(unit)

    def process_node(self, testline_object):
        self.process_units(self._get_proper_unit(testline_object.system_module))
        if testline_object.rms:
            self.add_rmods_from_unit(testline_object.rms)
        if testline_object.slave:
            self.process_units(self._get_proper_unit(testline_object.slave.system_module))

    def process_classical_bts(self, testline_object):
        for du in testline_object.dus:
            self.process_units(self._get_proper_unit(du.airscale))
            if du.rus:
                self.add_rmods_from_unit(du.rus)
        if testline_object.slave:
            self.process_units(self._get_proper_unit(testline_object.slave.dus[0].airscale))

    @staticmethod
    def _get_proper_unit(taf_object):
        return getattr(taf_object, 'common_units') or getattr(taf_object, 'core_units')

    def gather_mumin_console_logs(self, path: str):
        test_logger(f"Gathering MUMIN logs")
        try:
            for alias in self.rf_diagnostic_card.rmod_connections:
                self.rf_diagnostic_card.download_log(alias=alias, target_filepath=f"{path}/{alias}_console_log.txt")
        except Exception as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

    def add_rmods_from_unit(self, unit_rmods):
        for ru in (unit_rmods or []):
            if ru.lmi:
                if not any(ru.serial_number == lmi_rmod.serial_number for lmi_rmod in self.lmi_rmods):
                    test_logger(f"Detected RU {ru.serial_number} with mumin/lmi")
                    self.lmi_rmods.add(ru)

    def add_rmods_from_common_unit(self, common_unit):
        for bb in (common_unit.capacity_units or []):
            self.add_rmods_from_unit(bb.rus)

    def setup_rmod_connections(self, ru):
        return verify_function_x_times_with_ret(3, 20, self.rf_diagnostic_card.setup_connections, ru,
                                                ru.serial_number)

    @function_wrapper
    def gather_mumin_snapshot(self, rmod_sn: str, log_dir: str):
        try:
            if rmod_sn in self.rf_diagnostic_card.rmod_connections:
                test_logger(f"Collecting snapshot for Rmod with SN {rmod_sn}")
                self.rf_diagnostic_card.take_snapshot(alias=rmod_sn, target_path_on_vm=log_dir)
            else:
                test_logger(f"No Rmod with SN {rmod_sn} found for snapshot collection", "warn")
        except Exception as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

    @function_wrapper
    def trigger_mumin_snapshot(self, rmod_sn: str, logs_dir: str):
        def take_snapshot(alias: str, target_path_on_vm: str):
            self.rf_diagnostic_card.take_snapshot(alias=alias, target_path_on_vm=target_path_on_vm)

        try:
            if rmod_sn in self.rf_diagnostic_card.rmod_connections:
                test_logger(f"Triggering snapshot on Rmod with SN {rmod_sn}")
                wait_until_success(180, 30, take_snapshot, rmod_sn, f"{logs_dir}/mumin_logs")
            else:
                test_logger(f"No Rmod with SN {rmod_sn} found for snapshot triggering")
        except Exception as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug")

    def mumin_gather_snapshot_check(self, rmods_sn: set, logs_dir: str):
        try:
            for rmod_serial_number in (rmods_sn or {}):
                self.trigger_mumin_snapshot(rmod_serial_number, logs_dir)
        except Exception as e:
            test_logger(e, "error")

    def add_ru_to_lmi_rmods(self, node):
        for ru in node['mumin_config']:
            if ru.lmi:
                if not any(ru.serial_number == lmi_rmod.serial_number for lmi_rmod in self.lmi_rmods):
                    test_logger(f"Detected RU {ru.serial_number} with mumin/lmi")
                    self.lmi_rmods.add(ru)

    def execute_command_on_rmod(self, command: str, rmod_serial: str, wait_time: int = 30, wait_on_rmod: int = 120):
        self.wait_till_loging_possible(alias=rmod_serial, timeout=wait_on_rmod)
        return self.rf_diagnostic_card.execute_command(cmd=command, alias=rmod_serial, wait_time=wait_time)

    @function_wrapper
    def reconnect_rmod(self, alias: str):
        self.rf_diagnostic_card.disconnect(alias)
        self.setup_rmod_from_serial(alias)

    def wait_till_loging_possible(self, alias: str, timeout: int = 300):
        def check_rmod_connection():
            rmod_info = self.rf_diagnostic_card._diagnostic_card._rmod_connections[alias].rmod_info
            test_logger(rmod_info, "DEBUG")
            loggin_possible = rmod_info.get("login_possible")
            if not loggin_possible:
                raise
        wait_until_success(timeout, 30, check_rmod_connection)
